diff --git a/src/backends/vulkan/shaders/f16.glsl b/src/backends/vulkan/shaders/f16.glsl
index 3f1d6918..8489232a 100644
--- a/src/backends/vulkan/shaders/f16.glsl
+++ b/src/backends/vulkan/shaders/f16.glsl
@@ -8,13 +8,12 @@ float f16_to_f32(uint h) {
     uint sign = (h & 0x8000u) << 16u;
     uint m = h & 1023u;
     uint bits;
-    if (e == 0u) {
-        if (m == 0u) bits = sign;
-        else {
-            uint shift = uint(10 - findMSB(m));
-            bits = sign | ((113u - shift) << 23u) | (((m << shift) & 1023u) << 13u);
-        }
-    } else bits = sign | 0x7f800000u | (m << 13u);
+    if (e == 31u) bits = sign | 0x7f800000u | (m << 13u);
+    else if (m == 0u) bits = sign;
+    else {
+        uint shift = uint(10 - findMSB(m));
+        bits = sign | ((113u - shift) << 23u) | (((m << shift) & 1023u) << 13u);
+    }
     return uintBitsToFloat(bits);
 }
